import { test, expect } from '@playwright/test';

test.describe('Onboarding Tour Modal - Step Advancement', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/onboarding');
  });

  test('should advance through onboarding tour steps when next button is clicked', async ({ page }) => {
    // Verify onboarding modal is visible
    const modal = page.getByRole('dialog', { name: /onboarding tour/i });
    await expect(modal).toBeVisible();

    // Verify step 1 content is displayed
    const step1Title = page.getByText('Welcome to our app');
    await expect(step1Title).toBeVisible();

    // Verify step 1 description is visible
    const step1Description = page.getByText('This tour will guide you through key features.');
    await expect(step1Description).toBeVisible();

    // Click next button to advance to step 2
    const nextButton = page.getByRole('button', { name: /next/i });
    await nextButton.click();

    // Verify step 2 content is displayed
    const step2Title = page.getByText('Feature 1');
    await expect(step2Title).toBeVisible();

    // Verify step 2 description is visible
    const step2Description = page.getByText('Explore our powerful analytics dashboard.');
    await expect(step2Description).toBeVisible();

    // Click next button to advance to step 3
    await nextButton.click();

    // Verify step 3 content is displayed
    const step3Title = page.getByText('Feature 2');
    await expect(step3Title).toBeVisible();

    // Verify step 3 description is visible
    const step3Description = page.getByText('Manage your projects with ease.');
    await expect(step3Description).toBeVisible();

    // Click next button to advance to final step
    await nextButton.click();

    // Verify final step content is displayed
    const step4Title = page.getByText('Get Started');
    await expect(step4Title).toBeVisible();

    // Click finish button to close modal
    const finishButton = page.getByRole('button', { name: /finish/i });
    await finishButton.click();

    // Verify modal is closed
    await expect(modal).not.toBeVisible();
  });

  test('should handle edge case of clicking next button on last step', async ({ page }) => {
    // Verify onboarding modal is visible
    const modal = page.getByRole('dialog', { name: /onboarding tour/i });
    await expect(modal).toBeVisible();

    // Advance to step 3
    const nextButton = page.getByRole('button', { name: /next/i });
    await nextButton.click();
    const step2Title = page.getByText('Feature 1');
    await expect(step2Title).toBeVisible();

    await nextButton.click();
    const step3Title = page.getByText('Feature 2');
    await expect(step3Title).toBeVisible();

    // Verify progress indicator shows 3 of 4 steps
    const progressIndicator = page.getByText('3 of 4');
    await expect(progressIndicator).toBeVisible();

    // Click next button on last step
    await nextButton.click();

    // Verify final step is displayed
    const step4Title = page.getByText('Get Started');
    await expect(step4Title).toBeVisible();

    // Verify progress indicator shows 4 of 4 steps
    const finalProgressIndicator = page.getByText('4 of 4');
    await expect(finalProgressIndicator).toBeVisible();

    // Verify finish button is visible and enabled
    const finishButton = page.getByRole('button', { name: /finish/i });
    await expect(finishButton).toBeVisible();
    await expect(finishButton).toBeEnabled();

    // Verify next button is disabled on last step
    await expect(nextButton).toBeDisabled();

    // Click finish button to close modal
    await finishButton.click();

    // Verify modal is closed
    await expect(modal).not.toBeVisible();
  });
});
